/**
 * FOOD1 storybook food library: 200 foods from every region and era, raw and cooked, each a seeded still life (its
 * vessel, table, light mood and the visual tells that make it read) built from the kit (`food-kit.ts`,
 * `food-dishes.ts`). `foodStillLife` (`food-still-life.ts`) frames and renders an entry.
 *
 * Grouping data: `region` (where the dish belongs), `era` (ancient earthenware, traditional, vintage enamelware,
 * modern minimal plating), `state` (raw, cooked, baked, fermented, preserved, prepared) and `group` (fruit,
 * vegetable, pantry, bread, sweet, dairy, meat, seafood, soup, main, street, drink).
 */
import { fbm, fbm3, worley, worley3 } from "../anatomy/foundation-raster";
import { crustColour } from "./food-physics";
import { flatbreadSolid } from "./food-textures";
import { blade, box, displace, ellipsoid, lathe, merge, reseed, rng, slab, sweep, transform } from "./food-mesh";
import type { Mesh, V3 } from "./food-mesh";
import type { Part, SurfaceFn } from "./food-scene";
import { dewOn, levelIn, liquidIn, profile, vessel } from "./food-stage";
import type { MoodId, Vessel, VesselKind } from "./food-stage";
import {
  C, broth, butter, cheese, chocolate, clamp01, cream, crust, cutFace, dusted, fishFlesh, fried, glazeMeat, glazed, grains, gratin, leaf, mixInto, mushroom, noodle, nori,
  citrusPeel, mushroomCap, paperSkin, pepperSkin, potatoSkin, rawMeat, riceSurface, rootSkin, sauce, scaleInto, seared, setMix, skin, smooth, sponge, sst, stalk, syrup, tableSurface, tomatoSkin,
} from "./food-surfaces";
import type { SkinSpec, TableKind } from "./food-surfaces";
import { bananaHand, bulb, chilli, fruit, fruitBody, grapeBunch, grouped, halfFruit, heap, herbs, leafMesh, mushroomMesh, part, slices, sprinkle, taperRoot } from "./food-kit";
import {
  ball, boule, braid, breadSlice, cakeSlice, chashu, chunks, cookie, croissant, cupcake, dome, drink, dumpling, eggHalf, flatbread, friedEgg, jarContents, layeredBlock,
  longLoaf, macaron, makiSlices, nigiri, noodles, onigiri, pastaNest, pile, polyOutline, prawn, salmonFillet, steakCut, pretzel, ring, roastBird, roundCake, seat, sheet, shell, skewer, slabPiece, stack, steakSliced,
  gyozaPlate, riceMound, sector, tart, taco, tempuraShrimp, thickFill, wholeFish,
} from "./food-dishes";

export type FoodRegion = "east-asia" | "south-asia" | "southeast-asia" | "middle-east" | "europe" | "mediterranean" | "africa" | "latin-america" | "north-america" | "worldwide";
export type FoodEra = "ancient" | "traditional" | "vintage" | "modern";
export type FoodState = "raw" | "cooked" | "baked" | "fermented" | "preserved" | "prepared";
export type FoodGroup = "fruit" | "vegetable" | "pantry" | "bread" | "sweet" | "dairy" | "meat" | "seafood" | "soup" | "main" | "street" | "drink";

export const REGION_LABEL: Record<FoodRegion, string> = { "east-asia": "East Asia", "south-asia": "South Asia", "southeast-asia": "Southeast Asia", "middle-east": "Middle East", europe: "Europe", mediterranean: "Mediterranean", africa: "Africa", "latin-america": "Latin America", "north-america": "North America", worldwide: "Worldwide" };
export const ERA_LABEL: Record<FoodEra, string> = { ancient: "Ancient earthenware", traditional: "Traditional", vintage: "Vintage enamel", modern: "Modern minimal" };
export const GROUP_LABEL: Record<FoodGroup, string> = { fruit: "Fruit", vegetable: "Vegetables", pantry: "Pantry, spice and herbs", bread: "Bread", sweet: "Pastry and sweets", dairy: "Dairy and preserves", meat: "Meat", seafood: "Fish and seafood", soup: "Soups, stews and broths", main: "Plated mains", street: "Street food and dumplings", drink: "Drinks" };

export interface FoodView { elevation?: number; frame?: number; y?: number; z?: number }
export interface FoodEntry {
  id: string; name: string; region: FoodRegion; origin: string; era: FoodEra; state: FoodState; group: FoodGroup;
  vessel: VesselKind; size: number; table: TableKind; mood: MoodId;
  /** The visual tells that make it read: textures, light and the cooking that shows. */
  look: string;
  /** Steam strength 0…1 (hot dishes). */
  hot?: number;
  /** Settle the pieces into the vessel (default for fruit and vegetables): no piece passes through the vessel or another.
   *  `maxTilt` limits how far a piece may tip over (mushrooms stand). */
  settle?: boolean | { maxTilt?: number };
  view?: FoodView;
  build: (v: Vessel, seed: number) => Part[];
}

// ---- Special surfaces ---------------------------------------------------------------------------------------------------------

/** Pomegranate arils: ruby, glossy, packed in pale membranes. */
const arils: SurfaceFn = (s, o) => { const d = worley(9, s.o[0] / 3.2, s.o[2] / 3.2, 1), cell = 1 - sst(0.32, 0.45, d.f1); setMix(o.albedo, C("#efe0c8"), C("#9c0e22"), cell); scaleInto(o.albedo, 0.85 + 0.3 * cell * Math.sqrt(Math.max(0, 1 - d.f1 * 2))); o.height = cell * 0.8 * Math.sqrt(Math.max(0, 1 - d.f1 * 1.8)); o.rough = 0.08; o.coat = cell; o.coatRough = 0.03; o.mfp[0] = 4; o.mfp[1] = 0.6; o.mfp[2] = 0.6; o.trans = 0.8 * cell; };
/** A red onion's cut rings. */
const onionRings: SurfaceFn = (s, o) => { const r = Math.hypot(s.o[0], s.o[2]), ring = Math.abs(Math.sin(r * 0.9)), edge = 1 - sst(0, 0.12, Math.abs(((r * 0.9 / Math.PI) % 1) - 0.5) - 0.38); setMix(o.albedo, C("#efe2ea"), C("#8a2a58"), edge * 0.9); o.height = -edge * 0.1 + ring * 0.05; o.rough = 0.15; o.coat = 0.8; o.coatRough = 0.05; o.mfp[0] = 1.5; o.mfp[1] = 1.4; o.mfp[2] = 1.4; o.trans = 0.6; };
/** Lotus root slices: starchy cream with a ring of holes. */
const lotus: SurfaceFn = (s, o) => { const x = ((s.o[0] % 80) + 80) % 80 - 40, z = s.o[2], r = Math.hypot(x, z), a = Math.atan2(z, x); let hole = 0; for (let k = 0; k < 8; k++) { const ak = (k / 8) * Math.PI * 2 + 0.2, d = Math.hypot(x - Math.cos(ak) * 15, z - Math.sin(ak) * 15); hole = Math.max(hole, 1 - sst(4.2, 5, d)); } hole = Math.max(hole, 1 - sst(3, 3.8, r)); void a; setMix(o.albedo, C("#f0e6d0"), C("#3a2e22"), hole * 0.9); o.height = -hole * 2; o.rough = 0.3; o.coat = 0.4; o.mfp[0] = o.mfp[1] = o.mfp[2] = 1; };
/** Corn kernels in rows along a cob (u round, v along). */
const kernels: SurfaceFn = (s, o) => { const u = s.uv[0] * 16, v = s.uv[1] * 44 + (Math.floor(u) % 2) * 0.5, fu = u - Math.floor(u) - 0.5, fv = v - Math.floor(v) - 0.5, d = Math.hypot(fu * 1.1, fv), k = Math.sqrt(Math.max(0, 1 - d * d * 3.2)); setMix(o.albedo, C("#7a5a1a"), C("#f2c23a"), sst(0, 0.4, k)); scaleInto(o.albedo, 0.85 + 0.2 * fbm(3, u, v, 2)); o.height = k * 1.2; o.rough = 0.22; o.coat = 0.6 * k; o.coatRough = 0.06; o.mfp[0] = 1.5; o.mfp[1] = 1.1; o.mfp[2] = 0.3; o.trans = 0.3; o.occl = 0.6 + 0.4 * k; };
/** Watermelon flesh and rind by distance from the wedge's outer arc (`k.R`, apex at object x = −R/2). */
const melonWedge = (R: number, apex: [number, number], seedsOn = true): SurfaceFn => (s, o) => {
  const d = R - Math.hypot(s.o[0] - apex[0], s.o[2] - apex[1]);
  if (d < 6) { setMix(o.albedo, C("#1f4a1e"), C("#cfe0a4"), sst(2, 6, d)); if (d < 2.5) { const st = Math.sin(s.o[1] * 0.5 + Math.atan2(s.o[2], s.o[0]) * 20); mixInto(o.albedo, C("#3e6a2a"), sst(0, 0.8, st) * 0.7); } o.rough = 0.25; o.coat = 0.6; return; }
  setMix(o.albedo, C("#e8384a"), C("#f6a0a0"), sst(6, 14, d) * 0 + (1 - sst(6, 12, d)) * 0.4);
  const g = worley(5, s.o[0] / 2.2, s.o[2] / 2.2 + s.o[1] / 3, 1); o.height = (1 - Math.min(1, g.f1 * 1.8)) * 0.35; scaleInto(o.albedo, 0.85 + 0.25 * (1 - Math.min(1, g.f1 * 1.8)));
  if (seedsOn) { const sd = worley(7, s.o[0] / 9, s.o[2] / 9 + s.o[1] / 9, 0.8); if (sd.f1 < 0.11 && d > 25 && d < 60) { o.albedo[0] = 0.02; o.albedo[1] = 0.015; o.albedo[2] = 0.01; o.coat = 1; o.rough = 0.1; o.height += 0.3; } }
  o.rough = 0.15; o.coat = 0.8; o.coatRough = 0.04; o.mfp[0] = 3; o.mfp[1] = 0.8; o.mfp[2] = 0.8; o.trans = 0.6;
};
/** Netted cantaloupe skin. */
const netted: SurfaceFn = (s, o) => { const d = worley3(4, s.o[0] / 5, s.o[1] / 5, s.o[2] / 5), net = 1 - sst(0.0, 0.12, d.f2 - d.f1); setMix(o.albedo, C("#8a8a52"), C("#d9cfa6"), net); o.height = net * 0.6; o.rough = 0.7; o.occl = 0.75 + 0.25 * net; };
/** Hairy coconut husk fibres. */
const coconutHusk: SurfaceFn = (s, o) => { const f = fbm3(3, s.o[0] / 0.6, s.o[1] / 6, s.o[2] / 0.6, 3); setMix(o.albedo, C("#4a2e1a"), C("#9a6a3e"), clamp01(0.4 + f)); o.height = f * 0.6; o.rough = 0.85; o.sheen = 0.4; o.sheenTint = [0.5, 0.35, 0.2]; o.occl = 0.8 + 0.2 * f; };
/** Savoy cabbage: crinkled, veined, blue-green. */
const savoy: SurfaceFn = (s, o) => { const d = worley3(6, s.o[0] / 3, s.o[1] / 3, s.o[2] / 3), crink = Math.sqrt(Math.max(0, 1 - d.f1 * 1.7)), a = Math.atan2(s.o[2], s.o[0]), vein = 1 - sst(0, 0.05, Math.abs(Math.sin(a * 5 + s.o[1] * 0.03))); setMix(o.albedo, C("#4f7a3a"), C("#b6cf8a"), clamp01(vein * 0.8 + 0.15 * fbm3(2, s.o[0] / 9, s.o[1] / 9, s.o[2] / 9, 2))); o.height = crink * 0.9 - vein * 0.3; o.rough = 0.4; o.coat = 0.4; o.coatRough = 0.2; o.trans = 0.4; o.mfp[0] = 0.5; o.mfp[1] = 1; o.mfp[2] = 0.4; o.occl = 0.7 + 0.3 * crink; };
/** Fresh mozzarella: wet, milky, slightly torn. */
const mozz = smooth("#f8f5ec", { rough: 0.18, gloss: 0.6, scatter: 0.35, trans: 0.4, seed: 5, vary: 0.03 });
const tomatoSauce = (seed = 1) => sauce({ colour: "#a8200e", oil: "#d8541a", oiliness: 0.4, flecks: "#3a4a1a", fleckAmount: 0.4, gloss: 0.7, seed });
const curry = (colour: string, oil: string, seed = 1, flecks = "#2f3a18") => sauce({ colour, oil, oiliness: 0.6, flecks, fleckAmount: 0.6, gloss: 0.6, chunky: 0.4, seed });
const rice = (seed = 1, colour = "#f3efe6") => riceSurface(seed, colour);
const greenHerb = leaf("#3f7d2c", { veins: 3, gloss: 0.4 });

// small helpers
const P = part;
const at = (x: number, y: number, z: number): V3 => [x, y, z];
const flat = (y: number) => () => y;

