/** Find an entry by id. */
export const foodEntry = (id: string): FoodEntry | undefined => FOOD_LIBRARY.find(e => e.id === id);
/** A vessel for an entry. */
export const vesselFor = (e: FoodEntry, seed = 1): Vessel => vessel(e.vessel, e.size, seed);
/** The table top for an entry. */
export const tableFor = (e: FoodEntry, seed = 1) => tableSurface(e.table, seed);
